const trig = $('New Outlook Email').first().json;
const mailbox = String($('Configure Outlook Mailbox').first().json.mailbox_address || '').trim().toLowerCase();
if (!mailbox || !trig.id || !trig.conversationId) throw new Error('Connected mailbox, message ID, or conversation ID is missing. Check the app Microsoft connection and Outlook trigger.');
const ownAddresses = $('Configure Outlook Mailbox').first().json.own_addresses.map(x=>x.toLowerCase());
const byId = new Map();
for (const item of $input.all()) if (item.json?.id && item.json.conversationId === trig.conversationId && !item.json.isDraft) byId.set(item.json.id, item.json);
if (!byId.has(trig.id)) byId.set(trig.id, trig);
const addresses = list => (Array.isArray(list) ? list : []).map(x => String(x.emailAddress?.address || '').trim().toLowerCase()).filter(Boolean);
const rows = [...byId.values()].map(m => {
  const sender = String(m.from?.emailAddress?.address || m.sender?.emailAddress?.address || '').trim().toLowerCase();
  const outgoing = ownAddresses.includes(sender);
  const when = outgoing ? (m.sentDateTime || m.receivedDateTime) : (m.receivedDateTime || m.sentDateTime);
  if (!sender || !when || !Number.isFinite(Date.parse(when))) throw new Error('A conversation message has no sender or valid time.');
  const content = String(m.body?.content || m.bodyPreview || '');
  const html = String(m.body?.contentType || '').toLowerCase() === 'html';
  return { provider_key: m.id, provider_ref: m.id, internet_message_id: m.internetMessageId || null,
    direction: outgoing ? 'outgoing' : 'incoming', sender, to_addresses: addresses(m.toRecipients),
    cc_addresses: addresses(m.ccRecipients), subject: m.subject || trig.subject || '(no subject)',
    body_text: html ? (m.bodyPreview || '') : content, body_html: html ? content : '',
    body_loaded: !!m.body?.content, has_attachments: !!m.hasAttachments, occurred_at: new Date(when).toISOString() };
}).sort((a,b)=>a.occurred_at.localeCompare(b.occurred_at) || a.provider_key.localeCompare(b.provider_key));
if (!rows.length) throw new Error('Outlook returned no conversation messages.');
const current = rows.find(m => m.provider_key === trig.id);
if (!current) throw new Error('Triggered message is missing from conversation.');
// Keep every complete message in payload for the database. Bound only the AI prompt.
const plain = m => String(m.body_html
  ? m.body_html.replace(/<\/(?:p|div|br|li|tr|blockquote)[^>]*>/gi,'\n').replace(/<br\s*\/?>/gi,'\n').replace(/<[^>]*>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>')
  : m.body_text || '').replace(/[ \t]+/g,' ').replace(/\n\s*\n+/g,'\n').trim();
const describe = (m, body) => `From: ${m.sender}\nTo: ${m.to_addresses.join(', ')}\nDate: ${m.occurred_at}\n${body}`;
const older = rows.slice(0,-10);
const olderShown = older.length > 40 ? [...older.slice(0,2),...older.slice(-38)] : older;
const olderText = olderShown.map(m => describe(m,String(m.body_text || plain(m)).slice(0,500))).join('\n\n---\n\n');
const recent = rows.slice(-10);
const recentText = recent.map(m => describe(m,plain(m).slice(0,m.provider_key===trig.id?10000:3500))).join('\n\n---\n\n');
const omitted = older.length-olderShown.length;
const threadText = `${rows.length} messages in this Outlook conversation, oldest first. All complete messages are saved in the CRM.\n`+
  (older.length ? `Older messages (short excerpts${omitted?`; ${omitted} intermediate messages omitted from this AI prompt`:''}):\n${olderText}\n\n` : '')+
  `Most recent messages (longer excerpts):\n${recentText}`+
  (recent.some(m=>m.provider_key===trig.id)?'':`\n\nCurrent received message:\n${describe(current,plain(current).slice(0,10000))}`);
const payload = {mailbox, thread_key:trig.conversationId, subject:trig.subject || current.subject,
  trigger_id:trig.id, trigger_direction:current.direction, messages:rows};
return [{json:{threadText,subject:payload.subject,sender:current.sender,messageId:trig.id,
  triggerDirection:current.direction,payloadBase64:Buffer.from(JSON.stringify(payload),'utf8').toString('base64')}}];

const f = $('Find Customer').item.json;
const ctx = $('Load Customer Context').item.json;
const prev = $('Format Email Chain').item.json;
function list(arr, fn) { if (!arr || !arr.length) return 'none'; return arr.map(fn).join('; '); }
let contextText = '';
const emailBrain=$('Load Email Brain').first().json.email_brain;
const mc = Number(f.match_count || 0);
if (mc === 1 && f.customer) {
  const c = f.customer;
  contextText = 'Customer: ' + c.name + ' <' + c.email + '> (matched via ' + c.via + ')\n';
  contextText += 'Contacts: ' + list(ctx.contacts, x => x.name + ' <' + x.email + '>' + (x.phone ? ' ' + x.phone : '')) + '\n';
  contextText += 'Sites: ' + list(ctx.sites, x => x.name + ' (' + x.address + ')') + '\n';
  contextText += 'Equipment: ' + list(ctx.equipment, x => x.name + (x.model ? ' model ' + x.model : '') + (x.serial_number ? ' S/N ' + x.serial_number : '') + (x.battery_configuration ? ' [' + x.battery_configuration + ']' : '')) + '\n';
  contextText += 'Recent purchases: ' + list(ctx.purchases, x => x.name + ' on ' + x.occurred_on + (x.amount != null ? ' $' + x.amount : '')) + '\n';
  contextText += 'Recent services: ' + list(ctx.services, x => x.name + ' on ' + x.occurred_on + (x.notes ? ' - ' + x.notes : ''));
} else if (mc > 1) {
  contextText = 'WARNING: multiple CRM customers match this sender email. Do not reference any specific account details; answer generally and note the account needs manual review.';
}
return [{ json: { contextText:contextText+'\n\nEMAIL BRAIN (historical evidence and confirmed examples):\n'+JSON.stringify(emailBrain), customerMatched: mc === 1, matchCount: mc, subject: prev.subject, sender: prev.sender, threadText: prev.threadText, messageId: prev.messageId } }];

const body = String($json.draft || '');
const subject = String($json.subject || '');
const sender = String($json.sender || '').trim().toLowerCase();
const threadId = $('Persist Incoming Email').first().json.thread_id;
const messageId = $('Persist Incoming Email').first().json.message_id;
if (!body.trim() || !sender || !threadId || !messageId) throw new Error('Cannot save an incomplete reply draft.');
const payload = {body, subject, sender, thread_id:threadId, message_id:messageId};
return [{json:{payloadBase64:Buffer.from(JSON.stringify(payload),'utf8').toString('base64')}}];

